{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Trametinib, the highest-transfer analogue, had absolute oral bioavailability of 72.3% in patients with solid tumours using an oral tablet versus an i.v. microtracer; its cyclopropyl, aryl amide, and heteroaromatic features support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Apalutamide, a high-transfer analogue sharing fluoroaryl amide and cyclopropyl/heteroaromatic motifs, showed approximately 100% absolute oral bioavailability in a phase 1 i.v. microtracer study.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Regorafenib, a high-transfer fluoroaryl/heteroaromatic amide-containing drug, had 83% absolute oral bioavailability when given as an oral solution in patients with hepatocellular carcinoma.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Safinamide, a high-transfer ether/fluoro/amide-containing drug, had approximately 95% absolute oral bioavailability in patients/subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide, the lowest-F high-transfer analogue, still had mean absolute oral bioavailability of 32 ± 7% in normal subjects, which is above the 20% threshold and therefore does not contradict a high prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferred experimental absolute-bioavailability measurements are at or above 20%, with most high-transfer analogues showing 45-100% F; the strongest evidence (trametinib, apalutamide, regorafenib, safinamide) supports high oral bioavailability. Physicochemical solubility concerns are real but are outweighed by direct human PK evidence from closely transferable analogues.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule.",
    "The physicochemical prior indicates potential solubility limitations due to high molecular weight, high logD, and low fraction of sp3 carbons.",
    "The acrylamide and primary aromatic amine groups may introduce metabolic or reactivity liabilities not fully captured by the analogue set.",
    "Analogue transfer is based on assay-transfer scores rather than direct structural identity, leaving some residual uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

